// ---- src/lib/reminders.ts ----
// When Ledger notifies you, and what the notification says. Shared, word for word, by the app (reminders while it is open)
// and the `ledger-notify` edge function (reminders with Ledger closed), so both always agree. It therefore imports nothing:
// supabase/build-function.mjs pastes this file into the function as it is.
//
// A task reminds you on its due date at a time of day (default 08:00), and optionally some days earlier. A meeting reminds
// you some minutes before it starts (default 15). Each task, schedule and meeting can choose its own; null means "the default".

export interface NotifySettings {
  /** Off pauses every notification, on every device. */
  enabled: boolean;
  /** Days before the due date (0 = on the day). */
  taskDays: number[];
  /** "HH:MM": when task reminders arrive. */
  taskTime: string;
  /** Minutes before a meeting starts (0 = when it starts). */
  meetingMinutes: number[];
  /** Task titles and client names in the notification. Off shows only "2 tasks due today", for a lock screen others can see. */
  details: boolean;
}

export const DEFAULT_NOTIFY: NotifySettings = { enabled: true, taskDays: [0], taskTime: '08:00', meetingMinutes: [15], details: true };

/** The choices offered; anything in range is accepted, so a value set elsewhere is kept. */
export const TASK_DAY_CHOICES = [0, 1, 2, 3, 5, 7, 14, 30];
export const MEETING_MINUTE_CHOICES = [0, 5, 10, 15, 30, 60, 120, 1440];
export const MAX_REMINDERS = 4;
export const MAX_DAYS = 60;
export const MAX_MINUTES = 10080;

const TIME = /^([01]\d|2[0-3]):[0-5]\d$/;

function cleanList(raw: unknown, max: number): number[] | null {
  if (!Array.isArray(raw)) return null;
  const ok = raw.filter((n): n is number => Number.isInteger(n) && n >= 0 && n <= max);
  return [...new Set(ok)].sort((a, b) => b - a).slice(0, MAX_REMINDERS);
}
/** A task's or schedule's own days, or null for "use the default". */
export const cleanDays = (raw: unknown): number[] | null => cleanList(raw, MAX_DAYS);
/** A meeting's own minutes, or null for "use the default". */
export const cleanMinutes = (raw: unknown): number[] | null => cleanList(raw, MAX_MINUTES);

/** The workspace's notification settings, with defaults for anything missing or malformed. */
export function notifySettings(raw: unknown): NotifySettings {
  const r = (raw && typeof raw === 'object' ? raw : {}) as Partial<Record<keyof NotifySettings, unknown>>;
  return {
    enabled: typeof r.enabled === 'boolean' ? r.enabled : DEFAULT_NOTIFY.enabled,
    taskDays: cleanDays(r.taskDays) ?? DEFAULT_NOTIFY.taskDays,
    taskTime: typeof r.taskTime === 'string' && TIME.test(r.taskTime) ? r.taskTime : DEFAULT_NOTIFY.taskTime,
    meetingMinutes: cleanMinutes(r.meetingMinutes) ?? DEFAULT_NOTIFY.meetingMinutes,
    details: typeof r.details === 'boolean' ? r.details : DEFAULT_NOTIFY.details,
  };
}

// ---- time zones ----

const formatters = new Map<string, Intl.DateTimeFormat>();
function zoneFormat(tz: string): Intl.DateTimeFormat {
  let f = formatters.get(tz);
  if (!f) {
    try {
      f = new Intl.DateTimeFormat('en-US', { timeZone: tz, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
    } catch {
      f = zoneFormat('UTC');
    }
    formatters.set(tz, f);
  }
  return f;
}
/** How far the zone's clock is ahead of UTC at that instant, in ms. */
function offset(ts: number, tz: string): number {
  const p = Object.fromEntries(zoneFormat(tz).formatToParts(new Date(ts)).map((x) => [x.type, x.value]));
  return Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour % 24, +p.minute, +p.second) - Math.floor(ts / 1000) * 1000;
}
/** The instant a wall-clock date and time happen in a time zone. A time skipped by daylight saving lands an hour later. */
export function zonedInstant(date: string, time: string, tz: string): number {
  const [y, m, d] = date.split('-').map(Number);
  const [h, mi] = time.split(':').map(Number);
  const wall = Date.UTC(y, m - 1, d, h, mi);
  const first = wall - offset(wall, tz);
  return wall - offset(first, tz);
}
/** Today's date in a time zone, as YYYY-MM-DD. */
export function zonedToday(now: number, tz: string): string {
  const p = Object.fromEntries(zoneFormat(tz).formatToParts(new Date(now)).map((x) => [x.type, x.value]));
  return `${p.year}-${p.month}-${p.day}`;
}
export function addDaysISO(date: string, n: number): string {
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
}

// ---- what is due ----

export interface RemTask { id: string; clientId: string; scheduleId: string | null; title: string; dueDate: string; status: string; notifyDays?: number[] | null }
export interface RemMeeting { id: string; clientId: string | null; title: string; date: string; start: string; end: string; location?: string; notifyMinutes?: number[] | null }
export interface RemSchedule { id: string; notifyDays?: number[] | null }

export interface Reminder {
  /** Unique per item, lead and due date/time: moving a task re-arms its reminders, and nothing is announced twice. */
  key: string;
  at: number;
  kind: 'task' | 'meeting';
  id: string;
  /** Days (tasks) or minutes (meetings) before. */
  lead: number;
  title: string;
  client: string | null;
  date: string;
  start?: string;
  end?: string;
  location?: string;
}

const OPEN = new Set(['todo', 'in_progress', 'waiting']);

/** The days a task reminds you: its own, else its schedule's, else the workspace default. */
export function taskDays(t: RemTask, schedules: Map<string, RemSchedule>, s: NotifySettings): number[] {
  return t.notifyDays ?? (t.scheduleId ? schedules.get(t.scheduleId)?.notifyDays : null) ?? s.taskDays;
}
export const meetingMinutes = (m: RemMeeting, s: NotifySettings): number[] => m.notifyMinutes ?? s.meetingMinutes;

/** Every reminder that falls in (from, to], earliest first. */
export function remindersBetween(data: {
  tasks: RemTask[]; meetings: RemMeeting[]; schedules: RemSchedule[]; clientName: (id: string) => string | null | undefined;
  settings: NotifySettings; timeZone: string;
}, from: number, to: number): Reminder[] {
  const { settings: s, timeZone: tz } = data;
  if (!s.enabled) return [];
  const schedules = new Map(data.schedules.map((x) => [x.id, x]));
  const out: Reminder[] = [];
  for (const t of data.tasks) {
    if (!OPEN.has(t.status)) continue;
    for (const lead of taskDays(t, schedules, s)) {
      const at = zonedInstant(addDaysISO(t.dueDate, -lead), s.taskTime, tz);
      if (at > from && at <= to) out.push({ key: `t:${t.id}:${t.dueDate}:${lead}`, at, kind: 'task', id: t.id, lead, title: t.title, client: data.clientName(t.clientId) ?? null, date: t.dueDate });
    }
  }
  for (const m of data.meetings) {
    const startsAt = zonedInstant(m.date, m.start, tz);
    for (const lead of meetingMinutes(m, s)) {
      const at = startsAt - lead * 60_000;
      if (at > from && at <= to) {
        out.push({ key: `m:${m.id}:${m.date}T${m.start}:${lead}`, at, kind: 'meeting', id: m.id, lead, title: m.title,
          client: m.clientId ? data.clientName(m.clientId) ?? null : null, date: m.date, start: m.start, end: m.end, location: m.location || undefined });
      }
    }
  }
  return out.sort((a, b) => a.at - b.at || a.title.localeCompare(b.title));
}

// ---- what it says ----

export interface PushMessage {
  title: string;
  body: string;
  /** Same tag, same notification: a repeat replaces the earlier one instead of stacking. */
  tag: string;
  /** In-app path to open on a tap. */
  url: string;
  /** The reminder keys this message covers. */
  keys: string[];
}

const clip = (s: string, n: number) => (s.length > n ? `${s.slice(0, n - 1).trimEnd()}…` : s);
const plural = (n: number, one: string, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;
const dayLabel = (date: string) => new Intl.DateTimeFormat('en-GB', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'UTC' }).format(new Date(`${date}T12:00:00Z`));

/** "due today", "due tomorrow", "due in 3 days". */
export function dueWhen(lead: number): string {
  return lead === 0 ? 'due today' : lead === 1 ? 'due tomorrow' : `due in ${lead} days`;
}
/** "now", "in 15 min", "in 1 hour", "tomorrow at 10:00". */
export function meetingWhen(lead: number, start: string, date: string): string {
  if (lead === 0) return 'now';
  if (lead < 60) return `in ${lead} min`;
  if (lead < 1440 && lead % 60 === 0) return `in ${plural(lead / 60, 'hour')}`;
  if (lead < 1440) return `in ${Math.floor(lead / 60)} h ${lead % 60} min`;
  return lead === 1440 ? `tomorrow at ${start}` : `${dayLabel(date)} at ${start}`;
}
const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

/**
 * The notifications for reminders that fall due together: tasks at the same moment become one ("3 tasks due today"),
 * each meeting gets its own.
 */
export function messagesFor(reminders: Reminder[], details: boolean): PushMessage[] {
  const out: PushMessage[] = [];
  const taskGroups = new Map<number, Reminder[]>();
  for (const r of reminders) {
    if (r.kind === 'task') taskGroups.set(r.at, [...(taskGroups.get(r.at) ?? []), r]);
    else {
      const when = meetingWhen(r.lead, r.start!, r.date);
      const time = `${r.start}–${r.end}`;
      out.push({
        title: details ? `${cap(when)}: ${clip(r.title, 80)}` : `Meeting ${when}`,
        body: details ? [time, r.client, r.location].filter(Boolean).map((x) => clip(String(x), 80)).join(' · ') : time,
        tag: `ledger-meeting-${r.id}`, url: `/calendar?view=day&date=${r.date}&meeting=${r.id}`, keys: [r.key],
      });
    }
  }
  for (const [at, list] of taskGroups) {
    const leads = new Set(list.map((r) => r.lead));
    const same = leads.size === 1 ? dueWhen(list[0].lead) : null;
    if (list.length === 1) {
      const r = list[0];
      out.push({
        title: details ? `${cap(dueWhen(r.lead))}: ${clip(r.title, 80)}` : `A task is ${dueWhen(r.lead)}`,
        body: details ? [r.client && clip(r.client, 80), r.lead > 0 ? dayLabel(r.date) : null].filter(Boolean).join(' · ') || 'Open Ledger to see it.' : 'Open Ledger to see it.',
        tag: `ledger-task-${r.id}`, url: `/tasks?task=${r.id}`, keys: [r.key],
      });
      continue;
    }
    const shown = list.slice(0, 4).map((r) => clip(`${r.title}${r.client ? ` · ${r.client}` : ''}${same ? '' : ` (${dueWhen(r.lead)})`}`, 90));
    out.push({
      title: same ? `${plural(list.length, 'task')} ${same}` : `${plural(list.length, 'task')} coming up`,
      body: details ? [...shown, list.length > 4 ? `+${list.length - 4} more` : ''].filter(Boolean).join('\n') : 'Open Ledger to see them.',
      tag: `ledger-tasks-${at}`, url: '/tasks', keys: list.map((r) => r.key),
    });
  }
  return out.sort((a, b) => a.tag.localeCompare(b.tag));
}

/** Describes a reminder list for a person: "On the day and 3 days before at 08:00". */
export function describeDays(days: number[], time?: string): string {
  if (!days.length) return 'No notifications';
  const parts = [...days].sort((a, b) => a - b).map((d) => (d === 0 ? 'on the day' : d === 1 ? '1 day before' : d % 7 === 0 ? `${plural(d / 7, 'week')} before` : `${d} days before`));
  const text = parts.length === 1 ? parts[0] : `${parts.slice(0, -1).join(', ')} and ${parts[parts.length - 1]}`;
  return cap(text) + (time ? ` at ${time}` : '');
}
export function describeMinutes(minutes: number[]): string {
  if (!minutes.length) return 'No notifications';
  const parts = [...minutes].sort((a, b) => a - b).map((m) => (m === 0 ? 'when it starts'
    : m % 1440 === 0 ? `${plural(m / 1440, 'day')} before` : m % 60 === 0 ? `${plural(m / 60, 'hour')} before` : `${m} min before`));
  return cap(parts.length === 1 ? parts[0] : `${parts.slice(0, -1).join(', ')} and ${parts[parts.length - 1]}`);
}

// ---- plan.ts ----
// What one scheduled run of `ledger-notify` announces, from the database rows it read. Pure, so it is tested without a
// database or a network (supabase/tests/notify-plan.test.ts).

/** A reminder missed by more than this (the schedule did not run, the server was down) is dropped, not sent late. */
export const LATE_MS = 30 * 60_000;
/** How far ahead the rows are read: the longest reminder lead, plus a day either side for time zones. */
export const TASK_DAYS_AHEAD = 62;
export const MEETING_DAYS_AHEAD = 8;

type Row = Record<string, unknown>;
export interface RunRows { workspaces: Row[]; occurrences: Row[]; meetings: Row[]; schedules: Row[]; clients: Row[] }
export interface WorkspacePlan { workspaceId: string; reminders: Reminder[]; details: boolean }

const str = (v: unknown) => (v == null ? '' : String(v));
const hhmm = (v: unknown) => str(v).slice(0, 5);

/** The date range of rows a run needs, around today (UTC; a day of slack covers every time zone). */
export function windowDates(now: number) {
  const today = new Date(now).toISOString().slice(0, 10);
  return { from: addDaysISO(today, -1), tasksTo: addDaysISO(today, TASK_DAYS_AHEAD), meetingsTo: addDaysISO(today, MEETING_DAYS_AHEAD) };
}

/** Per workspace: the reminders due in the last LATE_MS up to now. */
export function planRun(rows: RunRows, now: number): WorkspacePlan[] {
  const clientName = new Map(rows.clients.map((c) => [str(c.id), str(c.name)]));
  return rows.workspaces.map((w) => {
    const id = str(w.id);
    const settings = notifySettings((w.settings as Row | null)?.notifications);
    const mine = <T extends Row>(list: T[]) => list.filter((r) => r.workspace_id === id);
    const reminders = remindersBetween({
      settings, timeZone: str(w.timezone) || 'Europe/Oslo', clientName: (c) => clientName.get(c),
      tasks: mine(rows.occurrences).map((o) => ({ id: str(o.id), clientId: str(o.client_id), scheduleId: o.schedule_id ? str(o.schedule_id) : null,
        title: str(o.title), dueDate: str(o.due_date), status: str(o.status), notifyDays: cleanDays(o.notify_days) })),
      schedules: mine(rows.schedules).map((s) => ({ id: str(s.id), notifyDays: cleanDays(s.notify_days) })),
      meetings: mine(rows.meetings).map((m) => ({ id: str(m.id), clientId: m.client_id ? str(m.client_id) : null, title: str(m.title), date: str(m.meeting_date),
        start: hhmm(m.start_time), end: hhmm(m.end_time), location: str(m.location), notifyMinutes: cleanMinutes(m.notify_minutes) })),
    }, now - LATE_MS, now);
    return { workspaceId: id, reminders, details: settings.details };
  }).filter((p) => p.reminders.length > 0);
}

/** The notifications for the reminders this run claimed (another run may have sent the rest). */
export function messagesForClaimed(plan: WorkspacePlan, claimed: Set<string>): PushMessage[] {
  return messagesFor(plan.reminders.filter((r) => claimed.has(r.key)), plan.details);
}

/** Seconds a push may wait for a device that is off: a meeting reminder is useless after the meeting starts. */
export function ttlFor(m: PushMessage, now: number, reminders: Reminder[]): number {
  const meeting = reminders.find((r) => r.kind === 'meeting' && m.keys.includes(r.key));
  if (!meeting) return 12 * 3600;
  const startsIn = Math.round((meeting.at + meeting.lead * 60_000 - now) / 1000);
  return Math.max(60, Math.min(12 * 3600, startsIn));
}

/** The test notification from Settings. */
export const TEST_MESSAGE = { title: 'Ledger notifications work', body: 'This device will get your reminders.', tag: 'ledger-test', url: '/settings' };

// ---- push.ts ----
// Web Push (RFC 8030) with payload encryption (RFC 8291, aes128gcm) and VAPID (RFC 8292), on WebCrypto, so it runs in
// Deno (the edge function), browsers and Node (the tests). Ledger's own copy of the code Home Memory's notify-partner uses,
// so the two apps never depend on each other. Tested in supabase/tests/push.test.ts.

const enc = new TextEncoder();
/** Bytes backed by a plain ArrayBuffer, which is what WebCrypto and fetch take. */
type Bytes = Uint8Array<ArrayBuffer>;

export function b64uToBytes(s: string): Bytes {
  const b = s.replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - (s.length % 4)) % 4);
  return Uint8Array.from(atob(b), (c) => c.charCodeAt(0));
}
export function bytesToB64u(bytes: Bytes): string {
  let s = '';
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
const concat = (...parts: Bytes[]) => {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let o = 0;
  for (const p of parts) { out.set(p, o); o += p.length; }
  return out;
};

async function hkdf(salt: Bytes, ikm: Bytes, info: Bytes, bytes: number): Promise<Bytes> {
  const key = await crypto.subtle.importKey('raw', ikm, 'HKDF', false, ['deriveBits']);
  return new Uint8Array(await crypto.subtle.deriveBits({ name: 'HKDF', hash: 'SHA-256', salt, info }, key, bytes * 8));
}

export type EncryptOptions = { salt?: Bytes; senderKeys?: CryptoKeyPair };

/** Encrypts `payload` for a push subscription. Returns the request body (header + one record). */
export async function encryptPayload(payload: Bytes, uaPublic: Bytes, authSecret: Bytes, opts: EncryptOptions = {}): Promise<Bytes> {
  if (uaPublic.length !== 65 || uaPublic[0] !== 4) throw new Error('bad subscription key');
  if (payload.length > 3993) throw new Error('payload too large'); // one 4096-byte record: 4096 - 16 tag - 1 delimiter - 86 header
  const salt = opts.salt ?? crypto.getRandomValues(new Uint8Array(16));
  const sender = opts.senderKeys ?? (await crypto.subtle.generateKey({ name: 'ECDH', namedCurve: 'P-256' }, true, ['deriveBits']));
  const asPublic = new Uint8Array(await crypto.subtle.exportKey('raw', sender.publicKey));
  const uaKey = await crypto.subtle.importKey('raw', uaPublic, { name: 'ECDH', namedCurve: 'P-256' }, false, []);
  const ecdh = new Uint8Array(await crypto.subtle.deriveBits({ name: 'ECDH', public: uaKey }, sender.privateKey, 256));
  const keyInfo = concat(enc.encode('WebPush: info\0'), uaPublic, asPublic);
  const ikm = await hkdf(authSecret, ecdh, keyInfo, 32);
  const cek = await hkdf(salt, ikm, enc.encode('Content-Encoding: aes128gcm\0'), 16);
  const nonce = await hkdf(salt, ikm, enc.encode('Content-Encoding: nonce\0'), 12);
  const aes = await crypto.subtle.importKey('raw', cek, 'AES-GCM', false, ['encrypt']);
  const cipher = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv: nonce }, aes, concat(payload, new Uint8Array([2]))));
  const rs = new Uint8Array([0, 0, 0x10, 0]); // 4096, big endian
  return concat(salt, rs, new Uint8Array([asPublic.length]), asPublic, cipher);
}

/** VAPID `Authorization` header value for a push endpoint. `privateD` is the 32-byte private scalar, `publicKey` the 65-byte point. */
export async function vapidAuthorization(endpoint: string, subject: string, publicKey: Bytes, privateD: Bytes, now = Date.now()): Promise<string> {
  const key = await crypto.subtle.importKey(
    'jwk',
    { kty: 'EC', crv: 'P-256', x: bytesToB64u(publicKey.slice(1, 33)), y: bytesToB64u(publicKey.slice(33, 65)), d: bytesToB64u(privateD) },
    { name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign'],
  );
  const part = (o: unknown) => bytesToB64u(enc.encode(JSON.stringify(o)));
  const signingInput = `${part({ typ: 'JWT', alg: 'ES256' })}.${part({ aud: new URL(endpoint).origin, exp: Math.floor(now / 1000) + 12 * 3600, sub: subject })}`;
  const sig = new Uint8Array(await crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, key, enc.encode(signingInput)));
  return `vapid t=${signingInput}.${bytesToB64u(sig)}, k=${bytesToB64u(publicKey)}`;
}

export type PushSub = { endpoint: string; p256dh: string; auth: string };

/** Builds and sends one push. Resolves with the push service's HTTP status. `ttl`: seconds the push service keeps trying a device that is off. */
export async function sendPush(sub: PushSub, payload: unknown, vapid: { subject: string; publicKey: string; privateKey: string }, ttl = 86400, fetchImpl: typeof fetch = fetch): Promise<number> {
  const body = await encryptPayload(enc.encode(JSON.stringify(payload)), b64uToBytes(sub.p256dh), b64uToBytes(sub.auth));
  const res = await fetchImpl(sub.endpoint, {
    method: 'POST',
    headers: {
      Authorization: await vapidAuthorization(sub.endpoint, vapid.subject, b64uToBytes(vapid.publicKey), b64uToBytes(vapid.privateKey)),
      'Content-Encoding': 'aes128gcm', 'Content-Type': 'application/octet-stream', TTL: String(ttl), Urgency: 'high',
    },
    body,
  });
  return res.status;
}

/** 404 and 410 mean the subscription is gone for good: forget it. */
export const isGone = (status: number) => status === 404 || status === 410;

/** Push services browsers use. The function only ever posts to these, whatever a device row says. */
const PUSH_HOSTS = [/^fcm\.googleapis\.com$/, /^([a-z0-9-]+\.)*push\.services\.mozilla\.com$/, /^web\.push\.apple\.com$/, /^[a-z0-9-]+\.notify\.windows\.com$/];
export function isPushEndpoint(endpoint: string): boolean {
  try {
    const u = new URL(endpoint);
    return u.protocol === 'https:' && !u.port && PUSH_HOSTS.some((h) => h.test(u.hostname));
  } catch {
    return false;
  }
}

// ---- handler ----
const cors = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};
const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...cors, 'Content-Type': 'application/json' } });

type Vapid = { publicKey: string; privateKey: string; subject: string };
type Device = { id: string; workspace_id: string; endpoint: string; p256dh: string; auth: string };

/** Reads every row of a query, 1000 at a time. */
async function all(q: () => { range(a: number, b: number): PromiseLike<{ data: unknown[] | null; error: unknown }> }): Promise<Record<string, unknown>[]> {
  const out: Record<string, unknown>[] = [];
  for (let from = 0; ; from += 1000) {
    const { data, error } = await q().range(from, from + 999);
    if (error) throw error;
    out.push(...((data ?? []) as Record<string, unknown>[]));
    if ((data ?? []).length < 1000) return out;
  }
}

/** Sends one message to some devices; forgets devices the push service says are gone. */
async function deliver(admin: SupabaseClient, devices: Device[], message: unknown, vapid: Vapid, ttl: number) {
  let sent = 0;
  const gone: string[] = [];
  await Promise.all(devices.map(async (d) => {
    if (!isPushEndpoint(d.endpoint)) return;
    try {
      const status = await sendPush(d, message, vapid, ttl);
      if (status >= 200 && status < 300) sent++;
      else if (isGone(status)) gone.push(d.id);
      else console.error('push refused', status);
    } catch (e) {
      console.error('push failed', e instanceof Error ? e.message : e);
    }
  }));
  if (gone.length) await admin.from('ledger_push_devices').delete().in('id', gone);
  return { sent, removed: gone.length };
}

// The scheduled run. Runs as the server (service role), so it is protected by a shared secret instead of a login.
async function runDue(req: Request, vapid: Vapid) {
  const secret = Deno.env.get('LEDGER_CRON_SECRET') ?? Deno.env.get('CRON_SECRET');
  if (!secret) return json({ error: 'not_configured' }, 503);
  if (req.headers.get('x-cron-secret') !== secret) return json({ error: 'unauthorized' }, 401);
  const admin = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);
  const now = Date.now();
  await admin.from('ledger_notify_status').upsert({ id: true, last_run: new Date(now).toISOString() });

  const devices = (await all(() => admin.from('ledger_push_devices').select('id, workspace_id, endpoint, p256dh, auth').order('id'))) as Device[];
  if (devices.length === 0) return json({ due: 0, sent: 0 });
  const ids = [...new Set(devices.map((d) => d.workspace_id))];
  const w = windowDates(now);
  const [workspaces, occurrences, meetings, schedules, clients] = await Promise.all([
    all(() => admin.from('ledger_workspaces').select('id, timezone, settings').in('id', ids).order('id')),
    all(() => admin.from('ledger_occurrences').select('id, workspace_id, client_id, schedule_id, title, due_date, status, notify_days')
      .in('workspace_id', ids).in('status', ['todo', 'in_progress', 'waiting']).gte('due_date', w.from).lte('due_date', w.tasksTo).order('id')),
    all(() => admin.from('ledger_meetings').select('id, workspace_id, client_id, title, meeting_date, start_time, end_time, location, notify_minutes')
      .in('workspace_id', ids).gte('meeting_date', w.from).lte('meeting_date', w.meetingsTo).order('id')),
    all(() => admin.from('ledger_schedules').select('id, workspace_id, notify_days').in('workspace_id', ids).not('notify_days', 'is', null).order('id')),
    all(() => admin.from('ledger_clients').select('id, workspace_id, name').in('workspace_id', ids).order('id')),
  ]);
  const plans = planRun({ workspaces, occurrences, meetings, schedules, clients } as RunRows, now);

  let due = 0, sent = 0, removed = 0;
  for (const plan of plans) {
    due += plan.reminders.length;
    // Claim first: only the keys inserted here are sent, so overlapping runs never announce the same thing twice.
    const { data: claimed, error } = await admin.from('ledger_push_sent')
      .upsert(plan.reminders.map((r) => ({ workspace_id: plan.workspaceId, key: r.key })), { onConflict: 'workspace_id,key', ignoreDuplicates: true })
      .select('key');
    if (error) { console.error('claim failed', error.message); continue; }
    const mine = devices.filter((d) => d.workspace_id === plan.workspaceId);
    for (const m of messagesForClaimed(plan, new Set((claimed ?? []).map((c) => String(c.key))))) {
      const { keys: _keys, ...payload } = m;
      const r = await deliver(admin, mine, payload, vapid, ttlFor(m, now, plan.reminders));
      sent += r.sent; removed += r.removed;
    }
  }
  // The log only has to outlive the reminders it covers.
  if (new Date(now).getUTCHours() === 3 && new Date(now).getUTCMinutes() < 5) {
    await admin.from('ledger_push_sent').delete().lt('sent_at', new Date(now - 90 * 86_400_000).toISOString());
  }
  return json({ due, sent, removed });
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: cors });
  if (req.method !== 'POST') return json({ error: 'method_not_allowed' }, 405);

  const publicKey = Deno.env.get('VAPID_PUBLIC_KEY');
  const privateKey = Deno.env.get('VAPID_PRIVATE_KEY');
  if (!publicKey || !privateKey) return json({ error: 'not_configured' }, 503);
  const vapid = { publicKey, privateKey, subject: Deno.env.get('VAPID_SUBJECT') ?? 'mailto:admin@example.com' };

  let body: { mode?: string; op?: string; endpoint?: string };
  try { body = await req.clone().json(); } catch { return json({ error: 'bad_request' }, 400); }
  if (body?.mode === 'due') return await runDue(req, vapid);

  // Everything else is for a signed-in person, and row level security decides what they may see.
  const auth = req.headers.get('Authorization');
  if (!auth) return json({ error: 'unauthorized' }, 401);
  const url = Deno.env.get('SUPABASE_URL')!;
  const asCaller = createClient(url, Deno.env.get('SUPABASE_ANON_KEY')!, { global: { headers: { Authorization: auth } } });
  const { data: who } = await asCaller.auth.getUser();
  if (!who?.user?.id) return json({ error: 'unauthorized' }, 401);
  const admin = createClient(url, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);

  if (body?.op === 'status') {
    const { data } = await admin.from('ledger_notify_status').select('last_run').maybeSingle();
    return json({ publicKey, lastRun: data?.last_run ?? null });
  }
  if (body?.op === 'test') {
    let q = asCaller.from('ledger_push_devices').select('id, workspace_id, endpoint, p256dh, auth');
    if (typeof body.endpoint === 'string') q = q.eq('endpoint', body.endpoint);
    const { data: devices, error } = await q;
    if (error) return json({ error: 'not_installed' }, 500);
    if (!devices?.length) return json({ sent: 0, removed: 0, devices: 0 });
    return json({ ...(await deliver(admin, devices as Device[], TEST_MESSAGE, vapid, 600)), devices: devices.length });
  }
  return json({ error: 'bad_request' }, 400);
});
